  private void collectTaxonomyFacetField(
      FacetsConfig config,
      FacetField facetField,
      Map<String, List<FacetField>> byField,
      Set<String> seenDims) {
    FacetsConfig.DimConfig dimConfig = config.getDimConfig(facetField.dim);
    if (dimConfig.multiValued == false) {
      rememberSeenDimension(seenDims, facetField.dim);
    }
    String indexFieldName = dimConfig.indexFieldName;
    List<FacetField> fields = byField.get(indexFieldName);
    if (fields == null) {
      fields = new ArrayList<>();
      byField.put(indexFieldName, fields);
    }
    fields.add(facetField);
    indexFieldCount++;
    indexSessionCount = byField.size();
  }

